#!/usr/bin/env node
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import cp from 'node:child_process';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { canonical,hashObject,resolveRuntimeRequest,makeRuntimeBundle } from './carrier.v1.mjs';

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../../..');
const SELF_PATH='.github/ai-router/bounded-exact-head-execution-carrier/self-test.v1.mjs';
const CARRIER_PATH='.github/ai-router/bounded-exact-head-execution-carrier/carrier.v1.mjs';
const REGISTRY_PATH='.github/ai-router/bounded-exact-head-execution-carrier/registry.v1.json';
const PRE_SELF='0a28e53bf1a4e5e40291af82cf8b8f75184c64ff';
const PRE_CARRIER='a61c6220b773a44b9f47513f56623b7f9fd7d788';
const RUNTIME='PAGE_EXCELLENCE_RUNTIME_FROM_CANONICAL_OPERATION_V1';
const ARCH='PAGE_EXCELLENCE_ARCHITECTURE_FROM_CANONICAL_OPERATION_V1';
const IMPL='PAGE_EXCELLENCE_IMPLEMENTATION_FROM_CANONICAL_OPERATION_V1';
const git=(args,cwd=ROOT)=>cp.execFileSync('git',args,{cwd,encoding:'utf8',maxBuffer:128*1024*1024,stdio:['ignore','pipe','pipe']});
const gitBlob=b=>crypto.createHash('sha1').update(Buffer.concat([Buffer.from(`blob ${b.length}\0`),b])).digest('hex');
const nonce=c=>c.repeat(64);
function exactBlob(sha){const b=cp.execFileSync('git',['cat-file','blob',sha],{cwd:ROOT});if(gitBlob(b)!==sha)throw new Error(`BLOB_IDENTITY_MISMATCH:${sha}`);return b;}
function previousRegression(){const t=fs.mkdtempSync(path.join(os.tmpdir(),'runtime-descriptor-prior-')),w=path.join(t,'w'),out=path.join(t,'out.json');let added=false;try{git(['worktree','add','--detach',w,git(['rev-parse','HEAD^{commit}']).trim()]);added=true;fs.writeFileSync(path.join(w,CARRIER_PATH),exactBlob(PRE_CARRIER));fs.writeFileSync(path.join(w,SELF_PATH),exactBlob(PRE_SELF));cp.execFileSync(process.execPath,[SELF_PATH,'--output',out],{cwd:w,env:{...process.env,BROWSER_MATRIX_EXACT_HEAD_REEXEC:'1'},stdio:['ignore','pipe','pipe'],maxBuffer:128*1024*1024});const r=JSON.parse(fs.readFileSync(out,'utf8'));if(r.result!=='PASS'||r.passed!==r.total||r.realMatrixSmoke?.result!=='PASS'||r.realMatrixSmoke?.r2Observability?.result!=='PASS')throw new Error('PRE_RUNTIME_FULL_REGRESSION_NONPASS');return {result:'PASS',selfTestBlob:PRE_SELF,carrierBlob:PRE_CARRIER,total:r.total,passed:r.passed,realMatrixSmoke:r.realMatrixSmoke};}finally{if(added){try{git(['worktree','remove','--force',w]);}catch{}}fs.rmSync(t,{recursive:true,force:true});}}
function fixture(){const head=git(['rev-parse','HEAD^{commit}']).trim(),sourceBlob='1'.repeat(40),scope='2'.repeat(64);const findings={schema:'CONTEXTUAL_ARCHITECTURE_FINDINGS_v1',implementationClass:'EXISTING_CONSTRUCT_ADOPTION',classificationRationale:'Synthetic runtime descriptor resolution fixture.',existingConstructSearch:{executed:true,searchedScopes:[`fixture@${head}`]},exactSourceConstructIdentities:[{sourceId:'FIXTURE',path:CARRIER_PATH,commitSha:head,gitBlobSha:sourceBlob,adoptionDisposition:'ADOPT_IMPLEMENTATION_SOURCE'}],adoptionMatrix:[{sourceId:'FIXTURE',sourceRelation:'IMPLEMENTATION_SOURCE',adoptedCapabilities:['FIXTURE'],adaptations:[],exclusions:[]}],visualArchitectureAuthority:{authorityHolder:'EXISTING_SOURCE_CONSTRUCTS_WITH_BOUNDED_ADAPTER',contentAdapterMayDefineVisualArchitecture:false},prohibitedSubstituteArchitectures:['SUBSTITUTE'],requiredRuntimeConditions:['RUNTIME'],separateNewConstructAuthority:null};const implFindings=Object.fromEntries(['CONTEXTUAL_ARCHITECTURE_BINDING_PRESERVED','SEMANTIC_MARKUP','FOCUS_MANAGEMENT','KEYBOARD_MODEL','STATE_RECOVERY','BUNDLE_STRUCTURE','RENDERING_STRATEGY','SEARCH_AND_GRAPH_COMPLEXITY','DEVICE_LAYOUT_RULES'].map(k=>[k,{result:'PASS',evidence:['synthetic']}])) ;const priorArchOp='SYNTHETIC_ARCH',archDigest=hashObject({descriptorId:ARCH,operationId:priorArchOp,subjectHead:head,findings});const op={schema:'REPOSITORY_OPERATION_REQUEST_v1',operationId:'SYNTHETIC_RUNTIME',projectId:'REPOSITORY_AI_ROUTER_INFRASTRUCTURE',lockScope:'SYNTHETIC:RUNTIME',exactGoverningHead:head,subjectIdentity:{experimentId:'synthetic_runtime',pageOperationSubjectHead:head,existingConstructSearchSources:[{sourceId:'FIXTURE',commitSha:head,files:[{path:CARRIER_PATH,gitBlobSha:sourceBlob}]}],pageArchitectureFindings:findings,pageImplementationFindings:{schema:'PAGE_EXCELLENCE_IMPLEMENTATION_FINDINGS_v1',findings:implFindings},pageArchitectureContinuity:{schema:'PAGE_EXCELLENCE_ARCHITECTURE_CONTINUITY_v1',priorOperationId:priorArchOp,priorDescriptorId:ARCH,subjectHead:head,architectureReceiptDigest:archDigest,nativeReceiptDigest:'3'.repeat(64)},pageImplementationContinuity:{schema:'PAGE_EXCELLENCE_IMPLEMENTATION_CONTINUITY_v1',priorOperationId:'SYNTHETIC_IMPL',priorDescriptorId:IMPL,priorLockGeneration:1,subjectHead:head,implementationExecutionReceiptDigest:'4'.repeat(64),terminalClosureNativeReceiptSha256:'5'.repeat(64),terminalDisposition:'PASS_CLOSED'}},allowedPaths:[CARRIER_PATH]};const proc={schema:'REPOSITORY_CONSTRUCTION_PROCEDURE_v1',procedureId:'SYNTH_RUNTIME',exactGoverningHead:head,exactAllowedRepositoryPaths:[CARRIER_PATH]};const rd=hashObject(op),pd=hashObject(proc),admission={schema:'REPOSITORY_OPERATION_ADMISSION_RECEIPT_v1',result:'ADMITTED_AND_LOCKED',operationId:op.operationId,projectId:op.projectId,operationStarted:true,workflowExecutionAuthorized:true,requestDigest:rd,procedureLocatorDigest:pd,lock:{lockAcquired:true,operationId:op.operationId,lockGeneration:1,lockScope:op.lockScope,scopeHash:scope}};const request={schema:'BOUNDED_EXACT_HEAD_EXECUTION_REQUEST_v1',requestId:'SYNTH_RUNTIME_REQ',descriptorId:RUNTIME,operationRequest:op,constructionProcedure:proc,admissionReceipt:admission,requestNonce:nonce('a')};const ledger={activeScopes:{[scope]:{operationId:op.operationId,lockGeneration:1,lockScope:op.lockScope,state:'ADMITTED_LOCKED',released:false,requestDigest:rd,procedureLocatorDigest:pd}}};return {request,ledger};}
function expect(name,fn,tests){try{fn();tests.push({name,result:'PASS'});}catch(e){tests.push({name,result:'FAIL',error:e.code??e.message});}}
export function runSelfTest(){const tests=[],prior=previousRegression(),reg=JSON.parse(fs.readFileSync(path.join(ROOT,REGISTRY_PATH),'utf8'));expect('RUNTIME_DESCRIPTOR_EXACTLY_ONE',()=>{const d=reg.descriptors.filter(x=>x.descriptorId===RUNTIME);if(d.length!==1||d[0].pagePhase!=='RUNTIME'||d[0].callerSuppliedBundleAllowed!==false||d[0].extraArgumentsAllowed!==false||d[0].environmentOverridesAllowed!==false||d[0].implementationContinuityDerivation!=='OPERATION_SUBJECT_IDENTITY_PAGE_IMPLEMENTATION_CONTINUITY_EXACT')throw new Error('descriptor');},tests);const f=fixture();expect('POSITIVE_RUNTIME_RESOLUTION',()=>{const r=resolveRuntimeRequest(f.request,{ledger:f.ledger});if(r.pageSubjectHead!==r.targetHead||r.descriptor.descriptorId!==RUNTIME||r.implementationContinuity.terminalDisposition!=='PASS_CLOSED')throw new Error('resolution');const t={raw:{locator:{toolsetId:'MANDATORY_PAGE_TOOLSET',version:'1.1.0'}},versions:{a:'1'}};const b=makeRuntimeBundle(r,t);if(b.bundle.phaseReceipts.length!==2||b.bundle.phaseReceipts[0].phase!=='ARCHITECTURE'||b.bundle.phaseReceipts[1].phase!=='IMPLEMENTATION')throw new Error('bundle');},tests);expect('CALLER_BUNDLE_REJECTED',()=>{const x=structuredClone(f.request);x.receiptBundle={};try{resolveRuntimeRequest(x,{ledger:f.ledger});}catch(e){if(e.code==='CARRIER_REQUEST_UNKNOWN_FIELD'||e.code==='ARBITRARY_COMMAND_FIELD_PROHIBITED')return;throw e;}throw new Error('unexpected pass');},tests);expect('IMPLEMENTATION_CONTINUITY_NONPASS_REJECTED',()=>{const x=structuredClone(f.request);x.operationRequest.subjectIdentity.pageImplementationContinuity.terminalDisposition='FAIL_CLOSED';const rd=hashObject(x.operationRequest);x.admissionReceipt.requestDigest=rd;const led=structuredClone(f.ledger);led.activeScopes[x.admissionReceipt.lock.scopeHash].requestDigest=rd;try{resolveRuntimeRequest(x,{ledger:led});}catch(e){if(e.code==='IMPLEMENTATION_CONTINUITY_INVALID')return;throw e;}throw new Error('unexpected pass');},tests);const pass=tests.every(t=>t.result==='PASS')&&prior.result==='PASS',total=prior.total+tests.length,passed=prior.passed+tests.filter(t=>t.result==='PASS').length;return {schema:'PAGE_EXCELLENCE_RUNTIME_DESCRIPTOR_EXTENSION_SELF_TEST_RECEIPT_v1',result:pass?'PASS':'FAIL',executionHead:git(['rev-parse','HEAD^{commit}']).trim(),total,passed,preRuntimeFullRegression:prior,runtimeDescriptorClosedWorld:true,callerSuppliedBundleAccepted:false,arbitraryCommandAccepted:false,authorityInflationObserved:false,tests};}
function main(){const a=process.argv.slice(2),i=a.indexOf('--output'),out=i>=0?a[i+1]:null,r=runSelfTest();if(out){fs.mkdirSync(path.dirname(path.resolve(out)),{recursive:true});fs.writeFileSync(path.resolve(out),JSON.stringify(r,null,2)+'\n');}else process.stdout.write(JSON.stringify(r,null,2)+'\n');if(r.result!=='PASS')process.exitCode=1;}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))main();
